entries.syntax:
WITH cte_name [(column_list)] AS (SELECT ...),
     next_cte AS (SELECT ... FROM cte_name)
SELECT ... FROM next_cte;

entries.example:
WITH base AS (
  SELECT column1 AS n FROM VALUES (1), (2)
), doubled AS (
  SELECT n * 2 AS n FROM base
)
SELECT n FROM doubled ORDER BY n;

SELECT a.id, b.label
FROM (VALUES (1), (2)) a(id)
LEFT JOIN (VALUES (1, 'one')) b(id, label) ON a.id = b.id;

SELECT column1 AS kind, COUNT(*) AS n
FROM VALUES ('a'), ('a'), ('b')
GROUP BY column1 HAVING COUNT(*) > 1;

SELECT column1, ROW_NUMBER() OVER (ORDER BY column1) AS rn
FROM VALUES (3), (1), (2)
QUALIFY rn <= 2;

entries.syntax:
MERGE INTO target USING source ON condition
WHEN MATCHED THEN UPDATE SET ...
WHEN NOT MATCHED THEN INSERT (...) VALUES (...);

entries.example:
MERGE INTO users t USING incoming s ON t.id = s.id
WHEN MATCHED THEN UPDATE SET name = s.name
WHEN NOT MATCHED THEN INSERT (id, name) VALUES (s.id, s.name);

entries.syntax:
CREATE [OR REPLACE] STAGE stage_name;
LIST @stage_name;
DROP STAGE [IF EXISTS] stage_name;

entries.example:
CREATE TEMPORARY TABLE doubled AS
WITH base AS (SELECT column1 AS n FROM VALUES (1), (2))
SELECT n * 2 AS n FROM base;

entries.syntax:
ALTER TABLE name ADD COLUMN column_name type;
TRUNCATE TABLE name;
DROP TABLE [IF EXISTS] name;

CREATE DATABASE name;
CREATE SCHEMA name;
DROP DATABASE name;
DROP SCHEMA name;

CREATE [OR REPLACE] VIEW name AS query;
SHOW VIEWS;
DROP VIEW [IF EXISTS] name;

CREATE DYNAMIC TABLE name TARGET_LAG = '1 MINUTE' WAREHOUSE = wh AS query;
ALTER DYNAMIC TABLE name REFRESH;
SHOW DYNAMIC TABLES;
DROP DYNAMIC TABLE name;

entries.example:
CREATE DYNAMIC TABLE user_summary
TARGET_LAG = '1 MINUTE' WAREHOUSE = COMPUTE_WH
AS SELECT COUNT(*) AS total FROM users;

entries.syntax:
CREATE WAREHOUSE name;
ALTER WAREHOUSE name RESUME;
ALTER WAREHOUSE name SUSPEND;
SHOW WAREHOUSES;
DROP WAREHOUSE name;

USE DATABASE name;
USE SCHEMA name;
USE WAREHOUSE name;
USE ROLE name;

entries.example:
USE DATABASE LEARNING_DB;
USE SCHEMA PUBLIC;
USE WAREHOUSE COMPUTE_WH;

entries.syntax:
SET name = expression;
SELECT $name;
UNSET name;

entries.example:
SET threshold = 10;
SELECT $threshold + 1;
UNSET threshold;

entries.syntax:
BEGIN; -- or START TRANSACTION
COMMIT;
ROLLBACK;

entries.example:
BEGIN;
INSERT INTO users VALUES (1, 'Alice');
COMMIT;

entries.syntax:
SHOW TABLES;
DESCRIBE TABLE name;
EXPLAIN SELECT ...;

entries.example:
SHOW TABLES;
DESCRIBE TABLE users;
EXPLAIN SELECT * FROM users;

entries.syntax:
CREATE USER name ...;
ALTER USER name ...;
DROP USER name;
CREATE ROLE name;
DROP ROLE name;
SHOW USERS;
SHOW ROLES;

GRANT ROLE child TO ROLE parent;
GRANT USAGE ON WAREHOUSE name TO ROLE role_name;
REVOKE USAGE ON WAREHOUSE name FROM ROLE role_name;
SHOW GRANTS;

CREATE [OR REPLACE] FUNCTION name(args) RETURNS type [LANGUAGE SQL] AS $$ expression $$;
SHOW FUNCTIONS;
DROP FUNCTION [IF EXISTS] name(types);

CREATE [OR REPLACE] PROCEDURE name(args) RETURNS type LANGUAGE SQL AS $$ BEGIN ... END; $$;
CALL name(args);
SHOW PROCEDURES;
DROP PROCEDURE name;

entries.example:
CREATE PROCEDURE greeting() RETURNS VARCHAR LANGUAGE SQL
AS $$ BEGIN RETURN 'hello'; END; $$;
CALL greeting();

entries.syntax:
DECLARE variable type DEFAULT expression;
BEGIN
  LET other type := expression;
  variable := expression;
  IF (condition) THEN ... ELSE ... END IF;
  RETURN expression;
END;

entries.example:
CREATE PROCEDURE answer() RETURNS INTEGER LANGUAGE SQL
AS $$ BEGIN LET n INTEGER := 40; RETURN n + 2; END; $$;
CALL answer();

entries.syntax:
CREATE [OR REPLACE] STREAM name ON TABLE source;
SELECT * FROM name;
SHOW STREAMS;
DROP STREAM name;

CREATE TASK name WAREHOUSE = wh SCHEDULE = '1 MINUTE' AS sql;
ALTER TASK name RESUME;
ALTER TASK name SUSPEND;
EXECUTE TASK name;
SHOW TASKS;
DROP TASK name;

entries.example:
CREATE TASK refresh_users WAREHOUSE = COMPUTE_WH
SCHEDULE = '1 MINUTE' AS INSERT INTO users VALUES (1, 'Alice');
ALTER TASK refresh_users RESUME;
